var SC=window.SugarCube; var v=SC.State.variables; var s=SC.setup; var ct=v.player.core_traits;
var log=[];
// baseline
log.push(['baseline globalCorr', ct.corruption, 'money', ct.money, 'wornCorr', s.getWornCorruption()]);
// B: buy revealing item while corruption low → gated
ct.corruption = 10; ct.money = 500;
log.push(['buy crop_top @corr10', s.buyItem('crop_top'), 'owned?', !!v.player.wardrobe['crop_top']]);
// C: raise corruption, buy → succeeds, money deducts, NOT auto-equipped
ct.corruption = 45; var m0=ct.money;
var bought = s.buyItem('crop_top');
log.push(['buy crop_top @corr45', bought, 'moneyDelta', ct.money-m0, 'equipped_top', v.player.equipped.top]);
// D: equip it → wornCorr MAX jumps; global corruption unchanged
var gc0=ct.corruption;
s.equipItem('crop_top');
log.push(['after equip crop_top: equipped_top', v.player.equipped.top, 'wornCorr', s.getWornCorruption(), 'wornBeauty', s.getWornBeauty(), 'globalCorr', ct.corruption, 'unchanged?', ct.corruption===gc0]);
return JSON.stringify(log);

var SC=window.SugarCube; var v=SC.State.variables; var s=SC.setup;
var log=[];
// find the sidewalk passage name
var p2l = s.passage_to_location || {};
var sidewalkPsg=null; for(var k in p2l){ if(p2l[k]==='loc_main_street_sidewalk'){ sidewalkPsg=k; break; } }
log.push(['sidewalk passage', sidewalkPsg]);
// dressed (crop_top + mom_jeans) → town allowed (null = OK)
log.push(['coverage dressed', s.checkLocationClothing(sidewalkPsg)]);
// strip to just bra → underdressed → blocked with message
s.unequipSlot('top'); s.unequipSlot('bottom'); s.unequipSlot('dress');
log.push(['coverage underdressed', s.checkLocationClothing(sidewalkPsg)]);
log.push(['wornCorr while stripped', s.getWornCorruption()]);
// worn_corruption>=25 condition (re-equip crop_top) evaluates true
s.equipItem('crop_top');
var cond={version:'1.0',logic:'AND',items:[{type:'worn_corruption',operator:'gte',value:25}]};
log.push(['worn_corruption>=25 satisfied (dressed revealing)', s.triggerConditionsSatisfied(cond)]);
s.unequipSlot('top');
log.push(['worn_corruption>=25 satisfied (top off)', s.triggerConditionsSatisfied(cond)]);
return JSON.stringify(log);
